// Package contracts renders the wire contract in pkg/api as TypeScript for the console
// (ADR-002, L0-003 rule 1: errors and rules are defined once). cmd/gencontracts writes the file;
// a test fails when the committed copy is stale.
package contracts

import (
	"encoding/json"
	"fmt"
	"slices"
	"strings"

	"github.com/enclavestack/platform/internal/domain"
	"github.com/enclavestack/platform/pkg/api"
)

// GeneratedPath is where the console keeps the generated file, relative to the repo root.
const GeneratedPath = "console/src/api/generated.ts"

func q(v any) string {
	b, _ := json.Marshal(v)
	return string(b)
}

// TypeScript returns the generated module.
func TypeScript() string {
	var b strings.Builder
	w := func(format string, a ...any) { fmt.Fprintf(&b, format, a...) }
	w("// Code generated by cmd/gencontracts from pkg/api. DO NOT EDIT.\n")
	w("// Regenerate with `make contracts` after changing pkg/api (L3-002, ADR-002).\n\n")

	kinds := make([]string, len(api.Kinds))
	for i, k := range api.Kinds {
		kinds[i] = string(k)
	}
	w("export const KINDS = %s as const;\nexport type Kind = (typeof KINDS)[number];\n\n", q(kinds))
	phases := make([]string, len(api.Phases))
	for i, p := range api.Phases {
		phases[i] = string(p)
	}
	w("export const PHASES = %s as const;\nexport type Phase = (typeof PHASES)[number];\n\n", q(phases))
	w("export const STEP_STATES = %s as const;\nexport type StepState = (typeof STEP_STATES)[number];\n\n",
		q([]string{string(api.StepPending), string(api.StepActive), string(api.StepDone), string(api.StepFailed)}))

	codes := make([]string, 0, len(api.ErrorCodes))
	for c := range api.ErrorCodes {
		codes = append(codes, string(c))
	}
	slices.Sort(codes)
	w("export const ERROR_STATUS = {\n")
	for _, c := range codes {
		w("  %s: %d,\n", c, api.ErrorCodes[api.ErrorCode(c)])
	}
	w("} as const;\nexport type ErrorCode = keyof typeof ERROR_STATUS;\n\n")
	fcodes := make([]string, len(api.FieldCodes))
	for i, f := range api.FieldCodes {
		fcodes[i] = string(f)
	}
	w("export const FIELD_CODES = %s as const;\nexport type FieldCode = (typeof FIELD_CODES)[number];\n\n", q(fcodes))

	prefixes := map[string]string{}
	steps := map[string][]string{}
	for _, k := range api.Kinds {
		prefixes[string(k)] = api.IDPrefix[k]
		steps[string(k)] = domain.StepNames[k]
	}
	w("export const ID_PREFIX: Record<Kind, string> = %s;\n", q(prefixes))
	w("export const STEP_NAMES: Record<Kind, readonly string[]> = %s;\n\n", q(steps))

	w("export const ACTIONS = %s as const;\n", q([]string{api.ActionRestart, api.ActionRedeploy, api.ActionReconcile, api.ActionRun, api.ActionRestore, api.ActionStart, api.ActionStop, api.ActionPurge, api.ActionTest, api.ActionRefresh}))
	w("export const HEADERS = { requestId: %s, idempotencyKey: %s, csrf: %s } as const;\n\n", q(api.HeaderRequestID), q(api.HeaderIdempotencyKey), q(api.HeaderCSRF))

	w("/** Validation rules (L3-002 §4) — the same numbers and patterns the server enforces. */\n")
	w("export const RULES = {\n")
	w("  namePattern: %s,\n  nameMin: %d,\n  nameMax: %d,\n", q(api.NamePatternSource), api.NameMinLen, api.NameMaxLen)
	w("  imagePattern: %s,\n  imageMax: %d,\n", q(api.ImagePatternSource), api.ImageMaxLen)
	w("  envKeyPattern: %s,\n  envMaxEntries: %d,\n  envValueMax: %d,\n", q(api.EnvKeyPatternSource), api.EnvMaxEntries, api.EnvValueMaxLen)
	w("  commandMaxItems: %d,\n  commandItemMax: %d,\n  portMin: %d,\n  portMax: %d,\n", api.CommandMaxItems, api.CommandItemMaxLen, api.PortMin, api.PortMax)
	w("  appMemoryMin: %d,\n  appMemoryMax: %d,\n  appMemoryDefault: %d,\n", api.AppMemoryMinMiB, api.AppMemoryMaxMiB, api.AppMemoryDefaultMiB)
	w("  cacheMemoryMin: %d,\n  cacheMemoryMax: %d,\n  cacheMemoryDefault: %d,\n", api.CacheMemoryMinMiB, api.CacheMemoryMaxMiB, api.CacheMemoryDefault)
	w("  secretValueMaxBytes: %d,\n  passwordMin: %d,\n  passwordMax: %d,\n", api.SecretValueMaxBytes, api.PasswordMinLen, api.PasswordMaxLen)
	w("  machineNameMax: %d,\n  emailMax: %d,\n  tokenNameMax: %d,\n  tokenMaxExpiryDays: %d,\n", api.MachineNameMaxLen, api.EmailMaxLen, api.TokenNameMaxLen, api.TokenMaxExpiryDays)
	w("  databaseVersions: %s,\n  defaultDatabaseVersion: %s,\n", q(api.DatabaseVersions), q(api.DefaultDBVersion))
	w("  databaseEngine: %s,\n  cacheEngine: %s,\n  cacheVersion: %s,\n", q(api.DatabaseEngine), q(api.CacheEngine), q(api.CacheVersion))
	w("  healthCheckTypes: %s,\n  strategies: %s,\n", q(api.HealthCheckTypes), q(api.Strategies))
	w("  healthIntervalMin: %d,\n  healthIntervalMax: %d,\n  healthIntervalDefault: %d,\n", api.HealthIntervalMin, api.HealthIntervalMax, api.HealthIntervalDefault)
	w("  healthTimeoutMin: %d,\n  healthTimeoutMax: %d,\n  healthTimeoutDefault: %d,\n", api.HealthTimeoutMin, api.HealthTimeoutMax, api.HealthTimeoutDefault)
	w("  healthRetriesMin: %d,\n  healthRetriesMax: %d,\n  healthRetriesDefault: %d,\n", api.HealthRetriesMin, api.HealthRetriesMax, api.HealthRetriesDefault)
	w("  healthStartPeriodMax: %d,\n  healthBudgetMaxSeconds: %d,\n  healthPathMax: %d,\n", api.HealthStartPeriodMax, api.HealthBudgetMaxSeconds, api.HealthPathMaxLen)
	w("  tlsModes: %s,\n  hostnameMax: %d,\n  hostLabelPattern: %s,\n  localhostSuffix: %s,\n", q(api.TLSModes), api.HostnameMaxLen, q(api.HostLabelPatternSource), q(api.LocalhostSuffix))
	w("  scheduleDescriptors: %s,\n  overlapPolicies: %s,\n  jobTimeoutMin: %d,\n  jobTimeoutMax: %d,\n  jobTimeoutDefault: %d,\n", q(api.Descriptors), q(api.OverlapPolicies), api.JobTimeoutMin, api.JobTimeoutMax, api.JobTimeoutDefault)
	w("  runStatuses: %s,\n  runTriggers: %s,\n", q(api.RunStatuses), q(api.RunTriggers))
	w("  backupPrefixDefault: %s,\n  backupPrefixPattern: %s,\n  backupScheduleDefault: %s,\n", q(api.BackupPrefixDefault), q(api.BackupPrefixPatternSource), q(api.BackupScheduleDefault))
	w("  backupKeepMin: %d,\n  backupKeepMax: %d,\n  backupKeepDefault: %d,\n  backupKeepDaysMax: %d,\n", api.BackupKeepMin, api.BackupKeepMax, api.BackupKeepDefault, api.BackupKeepDaysMax)
	w("  backupTimeoutMin: %d,\n  backupTimeoutMax: %d,\n  backupTimeoutDefault: %d,\n", api.BackupTimeoutMin, api.BackupTimeoutMax, api.BackupTimeoutDefault)
	w("  s3BucketPattern: %s,\n  restoreModes: %s,\n", q(api.S3BucketPatternSource), q([]string{api.RestoreNew, api.RestoreReplace}))
	w("  gitUrlMax: %d,\n  gitRefMax: %d,\n  buildArgsMax: %d,\n  gitDockerfileDefault: %s,\n  gitContextDefault: %s,\n", api.GitURLMaxLen, api.GitRefMaxLen, api.BuildArgsMax, q(api.GitDockerfileDefault), q(api.GitContextDefault))
	w("  networkPrefixMin: %d,\n  networkPrefixMax: %d,\n  subnetPrefixMin: %d,\n  subnetPrefixMax: %d,\n  subnetsMax: %d,\n  defaultSubnetName: %s,\n",
		api.NetworkPrefixMin, api.NetworkPrefixMax, api.SubnetPrefixMin, api.SubnetPrefixMax, api.SubnetsMax, q(api.DefaultSubnetName))
	w("  replicasMin: %d,\n  replicasMax: %d,\n  replicasDefault: %d,\n", api.ReplicasMin, api.ReplicasMax, api.ReplicasDefault)
	w("  protocols: %s,\n  egressDefaults: %s,\n  peerAny: %s,\n", q(api.Protocols), q(api.EgressDefaults), q(api.PeerAny))
	w("  firewallTargetsMax: %d,\n  firewallRulesMax: %d,\n  firewallPeersMax: %d,\n  firewallPortsMax: %d,\n", api.FirewallTargetsMax, api.FirewallRulesMax, api.FirewallPeersMax, api.FirewallPortsMax)
	w("  lbProtocols: %s,\n  algorithms: %s,\n  lbCheckTypes: %s,\n  lbTargetsMax: %d,\n", q(api.LBProtocols), q(api.Algorithms), q(api.LBCheckTypes), api.LBTargetsMax)
	w("  lbWeightMin: %d,\n  lbWeightMax: %d,\n  lbWeightDefault: %d,\n", api.LBWeightMin, api.LBWeightMax, api.LBWeightDefault)
	w("  lbIntervalMin: %d,\n  lbIntervalMax: %d,\n  lbIntervalDefault: %d,\n  lbTimeoutMin: %d,\n  lbTimeoutMax: %d,\n  lbTimeoutDefault: %d,\n",
		api.LBIntervalMin, api.LBIntervalMax, api.LBIntervalDefault, api.LBTimeoutMin, api.LBTimeoutMax, api.LBTimeoutDefault)
	w("  lbThresholdMin: %d,\n  lbThresholdMax: %d,\n  lbHealthyDefault: %d,\n  lbUnhealthyDefault: %d,\n", api.LBThresholdMin, api.LBThresholdMax, api.LBHealthyDefault, api.LBUnhealthyDefault)
	w("  dnsProviders: %s,\n  recordTypes: %s,\n  recordApex: %s,\n  recordLabelPattern: %s,\n", q(api.DNSProviders), q(api.RecordTypes), q(api.RecordApex), q(api.RecordLabelPatternSource))
	w("  recordTtlMin: %d,\n  recordTtlMax: %d,\n  recordTtlDefault: %d,\n  recordValuesMax: %d,\n  txtValueMax: %d,\n", api.RecordTTLMin, api.RecordTTLMax, api.RecordTTLDefault, api.RecordValuesMax, api.TXTValueMaxLen)
	w("  imageCatalog: %s,\n  snapshotImagePrefix: %s,\n  imageUrlMax: %d,\n  powerStates: %s,\n  volumeTypes: %s,\n",
		q(api.ImageCatalog), q(api.SnapshotImagePrefix), api.ImageURLMaxLen, q(api.PowerStates), q(api.VolumeTypes))
	w("  vmCpusMin: %d,\n  vmCpusMax: %d,\n  vmCpusDefault: %d,\n", api.VMCPUsMin, api.VMCPUsMax, api.VMCPUsDefault)
	w("  vmMemoryMin: %d,\n  vmMemoryMax: %d,\n  vmMemoryDefault: %d,\n  vmMemoryStep: %d,\n  vmMemoryHostReserve: %d,\n",
		api.VMMemoryMinMiB, api.VMMemoryMaxMiB, api.VMMemoryDefaultMiB, api.VMMemoryStepMiB, api.VMMemoryHostReserveMiB)
	w("  vmDiskMin: %d,\n  vmDiskMax: %d,\n  vmDiskDefault: %d,\n  vmDisksMax: %d,\n  vmPublishMax: %d,\n  diskSerialLen: %d,\n",
		api.VMDiskMinGiB, api.VMDiskMaxGiB, api.VMDiskDefaultGiB, api.VMDisksMax, api.VMPublishMax, api.DiskSerialLen)
	w("  sshKeysMax: %d,\n  sshKeyMax: %d,\n  userDataMaxBytes: %d,\n  sshPort: %d,\n", api.SSHKeysMax, api.SSHKeyMaxLen, api.UserDataMaxBytes, api.SSHPort)
	w("  volumeSizeMin: %d,\n  volumeSizeMax: %d,\n  volumeSizeDefault: %d,\n  mountsMax: %d,\n  mountPathMax: %d,\n",
		api.VolumeSizeMinGiB, api.VolumeSizeMaxGiB, api.VolumeSizeDefaultGiB, api.MountsMax, api.MountPathMaxLen)
	// v0.6 (L3-002 §9.4).
	w("  firewallKinds: %s,\n  placeableKinds: %s,\n", q(api.FirewallKinds), q(api.PlaceableKinds))
	w("  databaseEngines: %s,\n  databaseEngineVersions: %s,\n  databaseDefaultVersions: %s,\n", q(api.DatabaseEngines), q(api.DatabaseEngineVersions), q(api.DatabaseDefaultVersions))
	w("  queueVisibilityMin: %d,\n  queueVisibilityMax: %d,\n  queueVisibilityDefault: %d,\n", api.QueueVisibilityMin, api.QueueVisibilityMax, api.QueueVisibilityDefault)
	w("  retentionHoursMin: %d,\n  retentionHoursMax: %d,\n  queueRetentionDefault: %d,\n  topicRetentionDefault: %d,\n", api.RetentionHoursMin, api.RetentionHoursMax, api.QueueRetentionDefault, api.TopicRetentionDefault)
	w("  messageBytesMin: %d,\n  messageBytesMax: %d,\n  messageBytesDefault: %d,\n  maxReceivesMax: %d,\n", api.MessageBytesMin, api.MessageBytesMax, api.MessageBytesDefault, api.MaxReceivesMax)
	w("  subscriptionsMax: %d,\n  webhookUrlMax: %d,\n  messageAttributesMax: %d,\n  attributeValueMax: %d,\n  dedupIdMax: %d,\n", api.SubscriptionsMax, api.WebhookURLMaxLen, api.MessageAttributesMax, api.AttributeValueMaxLen, api.DedupIDMaxLen)
	w("  receiveMax: %d,\n  receiveWaitMax: %d,\n  deleteReceiptsMax: %d,\n  peekLimitMax: %d,\n  peekLimitDefault: %d,\n  webhookAttempts: %d,\n",
		api.ReceiveMaxMessages, api.ReceiveWaitMaxSeconds, api.DeleteReceiptsMax, api.PeekLimitMax, api.PeekLimitDefault, api.WebhookAttempts)
	w("  searchVersions: %s,\n  searchMemoryMin: %d,\n  searchMemoryMax: %d,\n  searchMemoryDefault: %d,\n  searchMemoryStep: %d,\n",
		q(api.SearchVersions), api.SearchMemoryMinMiB, api.SearchMemoryMaxMiB, api.SearchMemoryDefaultMiB, api.SearchMemoryStepMiB)
	w("  presets: %s,\n  prefixMax: %d,\n  transcodeTimeoutMin: %d,\n  transcodeTimeoutMax: %d,\n  transcodeTimeoutDefault: %d,\n",
		q(api.Presets), api.PrefixMaxLen, api.TranscodeTimeoutMin, api.TranscodeTimeoutMax, api.TranscodeTimeoutDefault)
	w("  concurrencyMin: %d,\n  concurrencyMax: %d,\n  concurrencyDefault: %d,\n  transcodeMemoryMin: %d,\n  transcodeMemoryMax: %d,\n  transcodeMemoryDefault: %d,\n  transcodeOutputDefault: %s,\n",
		api.ConcurrencyMin, api.ConcurrencyMax, api.ConcurrencyDefault, api.TranscodeMemoryMin, api.TranscodeMemoryMax, api.TranscodeMemoryDefault, q(api.TranscodeOutputDefault))
	w("  objectKeyMax: %d,\n  cdnTtlMin: %d,\n  cdnTtlMax: %d,\n  cdnTtlDefault: %d,\n  cdnSizeMin: %d,\n  cdnSizeMax: %d,\n  cdnSizeDefault: %d,\n",
		api.ObjectKeyMaxLen, api.CDNTTLMin, api.CDNTTLMax, api.CDNTTLDefault, api.CDNSizeMinMiB, api.CDNSizeMaxMiB, api.CDNSizeDefaultMiB)
	w("  emailModes: %s,\n  relayTlsModes: %s,\n  relayPortDefault: %d,\n  keepMessagesMin: %d,\n  keepMessagesMax: %d,\n  keepMessagesDefault: %d,\n",
		q(api.EmailModes), q(api.RelayTLSModes), api.RelayPortDefault, api.KeepMessagesMin, api.KeepMessagesMax, api.KeepMessagesDefault)
	w("  emailRecipientsMax: %d,\n  emailSubjectMax: %d,\n  emailBodyMaxBytes: %d,\n  emailListMax: %d,\n  emailListDefault: %d,\n",
		api.EmailRecipientsMax, api.EmailSubjectMaxLen, api.EmailBodyMaxBytes, api.EmailListMax, api.EmailListDefault)
	// v0.7 (L3-002 §10.7).
	w("  defaultProject: %s,\n  projectDescriptionMax: %d,\n  tokenProjectsMax: %d,\n", q(api.DefaultProject), api.ProjectDescriptionMaxLen, api.TokenProjectsMax)
	w("  widgetsMax: %d,\n  widgetTitleMax: %d,\n  widgetResourcesMax: %d,\n  alertResourcesMax: %d,\n", api.WidgetsMax, api.WidgetTitleMaxLen, api.WidgetResourceMax, api.AlertResourceMax)
	w("  conditionTypes: %s,\n  restartingKinds: %s,\n  runKinds: %s,\n  logKinds: %s,\n", q(api.ConditionTypes), q(api.RestartingKinds), q(api.RunKinds), q(api.LogKinds))
	w("  alertForMin: %d,\n  alertForMax: %d,\n  alertForDefault: %d,\n", api.AlertForMinutesMin, api.AlertForMinutesMax, api.AlertForMinutesDefault)
	w("  alertRestartsMin: %d,\n  alertRestartsMax: %d,\n  alertRestartsDefault: %d,\n", api.AlertRestartsMin, api.AlertRestartsMax, api.AlertRestartsDefault)
	w("  alertWindowMin: %d,\n  alertWindowMax: %d,\n  alertWindowDefault: %d,\n  alertRepeatMax: %d,\n  alertChannelsMax: %d,\n",
		api.AlertWindowMin, api.AlertWindowMax, api.AlertWindowDefault, api.AlertRepeatMax, api.AlertChannelsMax)
	w("  channelTypes: %s,\n  channelRecipientsMax: %d,\n  chatIdMax: %d,\n", q(api.ChannelTypes), api.ChannelRecipientsMax, api.ChatIDMaxLen)
	w("  logSourcesMax: %d,\n  logFilterMax: %d,\n  logFlushMin: %d,\n  logFlushMax: %d,\n  logFlushDefault: %d,\n  logFlushBucketDefault: %d,\n  logLabelsMax: %d,\n",
		api.LogSourcesMax, api.LogFilterMaxLen, api.LogFlushMin, api.LogFlushMax, api.LogFlushDefault, api.LogFlushBucketDefault, api.LogLabelsMax)
	w("  secretStoreProviders: %s,\n  storeRefreshMin: %d,\n  storeRefreshMax: %d,\n  storeRefreshDefault: %d,\n  vaultMountDefault: %s,\n  infisicalSiteDefault: %s,\n",
		q(api.SecretStoreProviders), api.StoreRefreshMin, api.StoreRefreshMax, api.StoreRefreshDefault, q(api.VaultMountDefault), q(api.InfisicalSiteDefault))
	w("  secretKeyMax: %d,\n  secretFieldMax: %d,\n", api.SecretKeyMaxLen, api.SecretFieldMaxLen)
	// v0.8 (L3-002 §11.9).
	w("  machineStates: %s,\n  placedKinds: %s,\n  dataKinds: %s,\n", q(api.MachineStates), q(api.PlacedKinds), q(api.DataKinds))
	w("  machineRef: %s,\n  machineRefPrefix: %s,\n", q(api.MachineRef), q(api.MachineRefPrefix))
	w("  machineLabelsMax: %d,\n  labelKeyPattern: %s,\n  labelValuePattern: %s,\n  agentPortDefault: %d,\n  tunnelPortDefault: %d,\n",
		api.MachineLabelsMax, q(api.LabelKeyPatternSource), q(api.LabelValuePatternSource), api.AgentPortDefault, api.TunnelPortDefault)
	w("} as const;\n\n")
	w("export const ROLES = %s as const;\n", q(api.Roles))
	w("export const METRIC_UNITS = %s as const;\nexport type MetricUnit = (typeof METRIC_UNITS)[number];\n",
		q([]string{api.UnitCores, api.UnitBytes, api.UnitBytesPerSecond, api.UnitPerSecond, api.UnitCount, api.UnitSeconds, api.UnitMilliseconds, api.UnitPercent}))
	w("/** The metric catalogue (L3-002 §10.4): name, unit, title and the kinds that have it. */\n")
	w("export const METRICS: readonly { name: string; unit: MetricUnit; title: string; kinds: readonly Kind[] }[] = %s;\n", q(api.Metrics))
	w("export const MACHINE_METRICS: readonly { name: string; unit: MetricUnit; title: string }[] = %s;\n\n", q(api.MachineMetrics))
	w("export const MANAGED = { objectStoreCredentials: %s, brokerCredentials: %s, passwordSecretSuffix: %s, systemOwner: %s } as const;\n",
		q(domain.ObjectStoreCredentialsSecret), q(domain.BrokerCredentialsSecret), q("-password"), q(domain.SystemOwner))
	return b.String()
}
